#include <string>
#include <vector>
#include <algorithm>

class Solution {
public:
    int longestCommonPrefix(std::vector<std::string>& words) {
        auto common_prefix_len = [](const std::string& a, const std::string& b) {
            int len = 0;
            int limit = std::min(a.size(), b.size());
            while (len < limit && a[len] == b[len]) len++;
            return len;
        };

        auto get_candidates = [](const std::string& s) {
            std::vector<std::string> cands;
            cands.push_back(s);
            for (size_t i = 0; i < s.size(); ++i) {
                cands.push_back(s.substr(0, i) + s.substr(i + 1));
            }
            return cands;
        };

        int max_lcp = 0;
        for (size_t i = 0; i + 1 < words.size(); ++i) {
            auto cands1 = get_candidates(words[i]);
            auto cands2 = get_candidates(words[i + 1]);
            for (const auto& c1 : cands1) {
                for (const auto& c2 : cands2) {
                    max_lcp = std::max(max_lcp, common_prefix_len(c1, c2));
                }
            }
        }

        return max_lcp;
    }
};

import java.util.*;

class Solution {
    public int longestCommonPrefix(String[] words) {
        int maxLcp = 0;
        for (int i = 0; i + 1 < words.length; i++) {
            List<String> cands1 = getCandidates(words[i]);
            List<String> cands2 = getCandidates(words[i + 1]);
            for (String c1 : cands1) {
                for (String c2 : cands2) {
                    maxLcp = Math.max(maxLcp, commonPrefixLen(c1, c2));
                }
            }
        }
        return maxLcp;
    }

    private List<String> getCandidates(String s) {
        List<String> cands = new ArrayList<>();
        cands.add(s);
        for (int i = 0; i < s.length(); i++) {
            cands.add(s.substring(0, i) + s.substring(i + 1));
        }
        return cands;
    }

    private int commonPrefixLen(String a, String b) {
        int len = 0;
        int limit = Math.min(a.length(), b.length());
        while (len < limit && a.charAt(len) == b.charAt(len)) len++;
        return len;
    }
}

