var longestCommonPrefix = function(words) {
    const commonPrefixLen = (a, b) => {
        let len = 0;
        const limit = Math.min(a.length, b.length);
        while (len < limit && a[len] === b[len]) len++;
        return len;
    };

    const getCandidates = (s) => {
        const cands = [s];
        for (let i = 0; i < s.length; i++) {
            cands.push(s.slice(0, i) + s.slice(i + 1));
        }
        return cands;
    };

    let maxLcp = 0;
    for (let i = 0; i + 1 < words.length; i++) {
        const cands1 = getCandidates(words[i]);
        const cands2 = getCandidates(words[i + 1]);
        for (const c1 of cands1) {
            for (const c2 of cands2) {
                const lcp = commonPrefixLen(c1, c2);
                if (lcp > maxLcp) maxLcp = lcp;
            }
        }
    }

    return maxLcp;
};
